html:
{%- set d = get_npd_print_data(doc.name) -%}
{%- macro fmtq(v) -%}
  {%- set n = (v or 0)|float -%}
  {%- if n == n|int -%}{{ n|int }}{%- else -%}{{ '{:g}'.format(n) }}{%- endif -%}
{%- endmacro -%}

<style>
  .npd { font-family: Arial, Helvetica, sans-serif; font-size: 11px; color: #222; }
  .npd-hdr { text-align:center; margin-bottom:6px; }
  .npd-co { font-size:12px; font-weight:bold; }
  .npd-title { font-size:13px; font-weight:bold; }
  .meta { width:100%; border-collapse:collapse; margin-bottom:8px; }
  .meta td { padding:2px 6px; font-size:10.5px; vertical-align:top; }
  .meta td.k { font-weight:bold; white-space:nowrap; }
  .kv { font-size:10.5px; margin:2px 0; }
  .kv b { display:inline-block; min-width:130px; }
  .tbl { width:100%; border-collapse:collapse; margin:8px 0; font-size:10px; }
  .tbl th { background:#2b2b2b; color:#fff; padding:4px 5px; border:1px solid #555; text-align:center; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
  .tbl td { padding:3px 5px; border:1px solid #ddd; text-align:center; }
  .tbl td.l { text-align:left; }
  .sec-lbl { font-weight:bold; font-size:10.5px; margin:8px 0 3px; }
  .footer-tbl { width:100%; border-collapse:collapse; margin-top:8px; font-size:10.5px; }
  .footer-tbl td { padding:2px 6px; }
  .footer-tbl td.k { font-weight:bold; white-space:nowrap; }
  .sign { width:60%; border-collapse:collapse; margin-top:26px; }
  .sign td { text-align:center; font-size:10px; border-top:1px solid #333; padding-top:4px; width:50%; }
  .sign .nm { border:0; padding-bottom:18px; font-weight:bold; }
</style>

<div class="npd">
  <div class="npd-hdr">
    {% if d.logo %}<img src="{{ d.logo }}" style="height:42px;display:block;margin:0 auto 2px">{% endif %}
    <div class="npd-co">Savinda Graphic Systems (Pvt) Ltd.</div>
    <div class="npd-title">{{ 'Flexo' if d.is_flexo else 'Offset' }} NPD Job Ticket ( No FSC ) ( NEW )</div>
  </div>

  <table class="meta">
    <tr>
      <td class="k">NPD No</td><td>: {{ doc.name }}</td>
      <td class="k">INQ No.</td><td>: {{ doc.inquiry or '' }}</td>
    </tr>
    <tr>
      <td class="k">NPD Date</td><td>: {{ doc.npd_date }}</td>
      <td class="k">Quote No</td><td>: {{ doc.quote_no or '' }}</td>
    </tr>
    <tr>
      <td class="k">Customer</td><td>: {{ doc.customer_name or '' }}</td>
      <td class="k">Sales p.</td><td>: {{ doc.sales_person or '' }}</td>
    </tr>
    <tr>
      <td class="k">Attention To</td><td>: {{ doc.attention_to or '' }}</td>
      <td class="k">Req. Sample Qty</td><td>: {{ doc.sample_qty or 0 }}</td>
    </tr>
  </table>

  <div class="kv"><b>Job Title</b>: {{ doc.job_title or '' }}</div>
  <div class="kv"><b>Material</b>: {{ doc.material or '' }}</div>
  <div class="kv"><b>Size</b>: {{ doc.size or '' }}</div>
  <div class="kv"><b>Color reference</b>: {{ doc.color_ref or '' }}</div>
  <div class="kv"><b>Colors</b>: {{ doc.colors or 0 }}</div>
  <div class="kv"><b>Finishings</b>: {{ doc.finishings or '' }}</div>
  <div class="kv"><b>Remarks</b>: {{ doc.remarks or '' }}</div>

  <table class="tbl">
    <thead>
      <tr>
        <th>#</th><th class="l" style="width:30%">Description</th><th>Size</th><th>Quantity</th>
        {% if d.is_flexo %}
        <th>Reel Area (sq_m)</th><th>Full Sheets</th><th>Cut Sheets</th><th>Ups</th><th>Cuts</th>
        {% else %}
        <th>Full Sheet Size</th><th>Cut Sheet Size</th><th>Full Sheets</th><th>Cut Sheets</th><th>Ups</th><th>Cuts</th>
        {% endif %}
      </tr>
    </thead>
    <tbody>
      {% for r in d.lines %}
      <tr>
        <td>{{ loop.index }}</td><td class="l">{{ r.item_name }}</td><td>{{ r.size }}</td><td>{{ fmtq(r.qty) }}</td>
        {% if d.is_flexo %}
        <td>{{ fmtq(r.reel_area) }}</td><td>{{ fmtq(r.full_sheets) }}</td><td>{{ fmtq(r.cut_sheets) }}</td><td>{{ r.ups }}</td><td>{{ r.cuts }}</td>
        {% else %}
        <td>{{ r.full_sheet_size }}</td><td>{{ r.cut_sheet_size }}</td><td>{{ fmtq(r.full_sheets) }}</td><td>{{ fmtq(r.cut_sheets) }}</td><td>{{ r.ups }}</td><td>{{ r.cuts }}</td>
        {% endif %}
      </tr>
      {% endfor %}
    </tbody>
  </table>

  {% if d.is_flexo %}
  <div class="sec-lbl">Product Development Details</div>
  <table class="tbl">
    <thead>
      <tr>
        <th>#</th><th class="l" style="width:24%">Description</th><th>Reel Length</th><th>Reel Width</th><th>Slit Width</th>
        <th>Repeat teeth</th><th>Repeat Ups</th><th>Repeat Gaps</th><th>Across Ups</th><th>Across Gaps</th><th>Across Material Width</th>
      </tr>
    </thead>
    <tbody>
      {% for r in d.lines %}
      <tr>
        <td>{{ loop.index }}</td><td class="l">{{ r.item_name }}</td><td>{{ fmtq(r.reel_length) }}</td><td>{{ fmtq(r.reel_width) }}</td><td>{{ r.slit_width }}</td>
        <td>{{ r.repeat_teeth }}</td><td>{{ r.repeat_ups }}</td><td>{{ r.repeat_gaps }}</td><td>{{ r.across_ups }}</td><td>{{ r.across_gaps }}</td><td>{{ r.material_width }}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>
  {% endif %}

  {% if d.materials %}
  <div class="sec-lbl">BOM Materials</div>
  <table class="tbl mat">
    <thead><tr><th class="l" style="width:60%">Item Name</th><th>Unit</th><th>Quantity</th></tr></thead>
    <tbody>
      {% for m in d.materials %}
      <tr><td class="l">{{ m.item_name }}</td><td>{{ m.uom }}</td><td>{{ fmtq(m.quantity) }}</td></tr>
      {% endfor %}
    </tbody>
  </table>
  {% endif %}

  <table class="footer-tbl">
    <tr>
      <td class="k">Winding Direction</td><td>: {{ doc.winding_direction or '' }}</td>
      <td class="k">No of inner pages</td><td>: {{ doc.no_of_inner_pages or 0 }}</td>
    </tr>
    <tr>
      <td class="k">No of ups per reel</td><td>: {{ doc.no_of_ups_per_reel or 0 }}</td>
      <td class="k">No of cover pages</td><td>: {{ doc.no_of_cover_pages or 0 }}</td>
    </tr>
    <tr>
      <td class="k">No of labels per reel</td><td>: {{ doc.no_of_labels_per_reel or 0 }}</td>
      <td class="k">Core size</td><td>: {{ doc.core_size or 0 }}</td>
    </tr>
  </table>

  <table class="sign">
    <tr>
      <td class="nm">{{ d.created_by }}</td>
      <td class="nm">{{ d.approved_by or 'Pending' }}</td>
    </tr>
    <tr>
      <td>Created by<br><span style="color:#666">{{ d.created_on or '' }}</span></td>
      <td>Approved by<br><span style="color:#666">{{ d.approved_on or '' }}</span></td>
    </tr>
  </table>
</div>
